using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Accounting.Abstractions;using OAS.Application.Common.Exceptions;using OAS.Domain.Accounting.Entities;
namespace OAS.Application.Accounting.Suppliers.Commands.SetSupplierStatus;
public sealed class SetSupplierStatusCommandHandler(IRepository<Supplier,Guid> suppliers,IPartyAccountProvisioningService accounts):IRequestHandler<SetSupplierStatusCommand>{public async Task Handle(SetSupplierStatusCommand r,CancellationToken ct){var e=await suppliers.GetForUpdateAsync(r.Id,ct)??throw new NotFoundException(nameof(Supplier),r.Id);try{if(!Convert.FromBase64String(r.Request.RowVersion).SequenceEqual(e.RowVersion))throw new ConcurrencyException("Supplier was modified by another user.");}catch(FormatException ex){throw new ConcurrencyException("Supplier row version is invalid.",ex);}e.SetActive(r.Request.IsActive);suppliers.Update(e);await accounts.SynchronizeAsync(e.AccountId,e.NameAr,e.NameEn,e.IsActive,ct);}}
